def shortestRemoval(nums):
    n = len(nums)
    l = 0
    while l + 1 < n and nums[l] <= nums[l + 1]:
        l += 1
    if l == n - 1:
        return 0
    r = n - 1
    while r > 0 and nums[r - 1] <= nums[r]:
        r -= 1
    best = min(n - l - 1, r)
    i, j = 0, r
    while i <= l and j < n:
        if nums[i] <= nums[j]:
            if j - i - 1 < best:
                best = j - i - 1
            i += 1
        else:
            j += 1
    return best
